export function useTouchLayout(width,height,coarse=false,seenTouch=false){return coarse||seenTouch||width<=900||height<=500;}
export function gameViewport(width,height,touchLayout=false){const scale=touchLayout?Math.min(width/1600,height/760):width/1600;return {scale,width:width/scale,height:height/scale};}
export function composeInput(keys,pointers){const values=new Set([...keys,...pointers.values()]);return Object.fromEntries(['right','left','rear','front','both','ability'].map(k=>[k,values.has(k)]));}
export function bindHoldControl(button,{canPress,onPress,onRelease}){button.addEventListener('pointerdown',e=>{e.preventDefault();if(button.disabled||!canPress())return;button.setPointerCapture(e.pointerId);onPress(e.pointerId,button.dataset.control);});const release=e=>onRelease(e.pointerId,button.dataset.control);for(const type of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(type,release);button.addEventListener('contextmenu',e=>e.preventDefault());}
export function touchInstructions(copy){return copy.replaceAll('Hold →','Hold DRIVE ▶').replaceAll('Tap Space','Tap BOTH').replaceAll('Hold Space','Hold BOTH').replaceAll('Space lifts','BOTH lifts').replaceAll('A / D','REAR / FRONT').replaceAll('Hold E','Hold ROCKET').replaceAll('Press E','Tap OPEN CHUTE').replaceAll('R to return','Tap Retry to return').replaceAll('R TO CHANGE YOUR LOADOUT','RETRY TO CHANGE YOUR GIFT').replaceAll('← → steer','◀ ▶ steer');}
